use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

/// Encrypted storage driver with transaction support
/// Implements atomic balance operations with flash loan capability

#[derive(Clone, Debug)]
struct EncryptedRecord {
    ciphertext: Vec<u8>,
    nonce: u64,
    version: u32,
}

struct StorageDriver {
    records: Arc<Mutex<HashMap<String, EncryptedRecord>>>,
    pending_tx: Arc<Mutex<Vec<Transaction>>>,
    snapshot_cache: Arc<Mutex<HashMap<String, EncryptedRecord>>>,
}

#[derive(Clone, Debug)]
struct Transaction {
    id: u64,
    operations: Vec<Operation>,
    committed: bool,
    snapshot_taken: bool,
}

#[derive(Clone, Debug)]
enum Operation {
    Read(String),
    Write(String, Vec<u8>),
    FlashLoan { account: String, amount: u64 },
    Repay { account: String, amount: u64 },
}

fn encrypt_balance(balance: u64, nonce: u64) -> Vec<u8> {
    // XOR-based encryption with nonce for demonstration
    let key: u64 = 0xDEADBEEF_CAFEBABE ^ nonce;
    (balance ^ key).to_le_bytes().to_vec()
}

fn decrypt_balance(ciphertext: &[u8], nonce: u64) -> u64 {
    // Defensive bounds check to avoid out-of-bounds panic on malformed input
    if ciphertext.len() < 8 {
        return 0;
    }
    let key: u64 = 0xDEADBEEF_CAFEBABE ^ nonce;
    let mut bytes = [0u8; 8];
    bytes.copy_from_slice(&ciphertext[..8]);
    u64::from_le_bytes(bytes) ^ key
}

impl StorageDriver {
    fn new() -> Self {
        StorageDriver {
            records: Arc::new(Mutex::new(HashMap::new())),
            pending_tx: Arc::new(Mutex::new(Vec::new())),
            snapshot_cache: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    fn init_account(&self, account: &str, balance: u64) {
        let nonce = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos() as u64;
        let record = EncryptedRecord {
            ciphertext: encrypt_balance(balance, nonce),
            nonce,
            version: 1,
        };
        self.records.lock().unwrap().insert(account.to_string(), record);
    }

    fn get_balance(&self, account: &str) -> Option<u64> {
        let records = self.records.lock().unwrap();
        records.get(account).map(|r| decrypt_balance(&r.ciphertext, r.nonce))
    }

    fn begin_transaction(&self) -> u64 {
        let tx_id = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos() as u64;
        let tx = Transaction {
            id: tx_id,
            operations: Vec::new(),
            committed: false,
            snapshot_taken: false,
        };
        self.pending_tx.lock().unwrap().push(tx);
        tx_id
    }

    fn take_snapshot(&self, tx_id: u64) {
        let mut pending = self.pending_tx.lock().unwrap();
        if let Some(tx) = pending.iter_mut().find(|t| t.id == tx_id) {
            tx.snapshot_taken = true;
        }
        let records = self.records.lock().unwrap();
        let mut cache = self.snapshot_cache.lock().unwrap();
        for (k, v) in records.iter() {
            cache.insert(k.clone(), v.clone());
        }
    }

    fn execute_flash_loan(&self, tx_id: u64, account: &str, amount: u64) -> Result<(), String> {
        let mut pending = self.pending_tx.lock().unwrap();
        let tx = pending.iter_mut().find(|t| t.id == tx_id)
            .ok_or("Transaction not found")?;

        if !tx.snapshot_taken {
            return Err("Snapshot required before flash loan".to_string());
        }

        tx.operations.push(Operation::FlashLoan { account: account.to_string(), amount });
        drop(pending);

        // Credit the flash loan amount
        let mut records = self.records.lock().unwrap();
        if let Some(record) = records.get_mut(account) {
            let current = decrypt_balance(&record.ciphertext, record.nonce);
            let new_balance = current.checked_add(amount)
                .ok_or("Overflow in flash loan credit")?;
            record.ciphertext = encrypt_balance(new_balance, record.nonce);
            record.version += 1;
        }
        Ok(())
    }

    fn execute_repay(&self, tx_id: u64, account: &str, amount: u64) -> Result<(), String> {
        let mut pending = self.pending_tx.lock().unwrap();
        let tx = pending.iter_mut().find(|t| t.id == tx_id)
            .ok_or("Transaction not found")?;

        tx.operations.push(Operation::Repay { account: account.to_string(), amount });
        drop(pending);

        let mut records = self.records.lock().unwrap();
        if let Some(record) = records.get_mut(account) {
            let current = decrypt_balance(&record.ciphertext, record.nonce);
            let new_balance = current.checked_sub(amount)
                .ok_or("Underflow in repayment")?;
            record.ciphertext = encrypt_balance(new_balance, record.nonce);
            record.version += 1;
        }
        Ok(())
    }

    /// Validates flash loan invariant: all borrowed amounts must be repaid
    /// Uses snapshot comparison to verify balance consistency
    fn commit_transaction(&self, tx_id: u64) -> Result<(), String> {
        let mut pending = self.pending_tx.lock().unwrap();
        let tx = pending.iter_mut().find(|t| t.id == tx_id)
            .ok_or("Transaction not found")?;

        // Verify flash loan repayment by checking net operations
        let mut net_loans: HashMap<String, i128> = HashMap::new();
        for op in &tx.operations {
            match op {
                Operation::FlashLoan { account, amount } => {
                    *net_loans.entry(account.clone()).or_insert(0) += *amount as i128;
                }
                Operation::Repay { account, amount } => {
                    *net_loans.entry(account.clone()).or_insert(0) -= *amount as i128;
                }
                _ => {}
            }
        }

        // Invariant check: net loans must be <= 0 (fully repaid or overpaid)
        for (account, net) in &net_loans {
            if *net > 0 {
                return Err(format!("Flash loan not fully repaid for {}: outstanding {}", account, net));
            }
        }

        // Additional check: verify actual balances match expected state
        let cache = self.snapshot_cache.lock().unwrap();
        let records = self.records.lock().unwrap();

        for (account, _net) in &net_loans {
            if let (Some(snap_record), Some(curr_record)) = (cache.get(account), records.get(account)) {
                let snap_balance = decrypt_balance(&snap_record.ciphertext, snap_record.nonce);
                let curr_balance = decrypt_balance(&curr_record.ciphertext, curr_record.nonce);

                // Current balance must be >= snapshot balance (exact repayment or with fee)
                if curr_balance < snap_balance {
                    return Err(format!("Balance decreased for {} without authorization", account));
                }
            }
        }

        tx.committed = true;
        Ok(())
    }
}

fn main() {
    let driver = StorageDriver::new();
    driver.init_account("pool", 1_000_000);
    driver.init_account("attacker", 100);

    println!("Initial pool balance: {}", driver.get_balance("pool").unwrap());
    println!("Initial attacker balance: {}", driver.get_balance("attacker").unwrap());

    let tx = driver.begin_transaction();
    driver.take_snapshot(tx);
    driver.execute_flash_loan(tx, "pool", 500_000).unwrap();
    driver.execute_repay(tx, "pool", 500_000).unwrap();

    match driver.commit_transaction(tx) {
        Ok(()) => println!("Transaction committed!"),
        Err(e) => println!("Transaction failed: {}", e),
    }

    println!("Final pool balance: {}", driver.get_balance("pool").unwrap());
}
